"""Dungeon quest lists: match outof.games dungeon pages to generated (OpenMap) dungeons by name.

Output is data/curated/dungeons.quests.generated.toml, merged by `pipeline.curated.load_dungeons`.
"""
from __future__ import annotations

from pathlib import Path

from pipeline.curated import name_key
from pipeline.poi import toml_key, write_text_atomic

HEADER = ("# Generated by `python -m pipeline dungeon-quests` from the outof.games dungeon pages "
          "(data/build/outofgames/dungeons). Do not edit; override in dungeons.toml.\n")


# outof.games names that differ from OpenMap's by more than case, punctuation and "The".
ALIASES = {name_key("The Temple of Atal'Hakkar"): name_key("Sunken Temple"),
           name_key("The Stockade"): name_key("Stormwind Stockade")}


def _wing_complex(name: str) -> str | None:
    """The complex of a wing name ("Scarlet Monastery - Library" -> key of "Scarlet Monastery")."""
    return name_key(name.split(" - ", 1)[0]) if " - " in name else None


def match_dungeons(pages: list[dict], dungeons: dict) -> tuple[list[tuple[dict, list[str]]], list[dict]]:
    """Match each page to generated dungeon keys: ([(page, [key, ...])], unmatched pages).

    Order of rules: the same normalised name (case, punctuation and "The" ignored); a whole-complex
    page ("Scarlet Monastery") matches every wing; a page of at least two words that all occur in exactly one
    dungeon name ("The Stockade" ~ "Stormwind Stockade").
    """
    by_name: dict[str, list[str]] = {}
    by_complex: dict[str, list[str]] = {}
    for key in sorted(dungeons):
        name = dungeons[key]["name"]
        by_name.setdefault(name_key(name), []).append(key)
        if (c := _wing_complex(name)) is not None:
            by_complex.setdefault(c, []).append(key)
    matched, unmatched = [], []
    for page in pages:
        pk = ALIASES.get(name_key(page["name"]), name_key(page["name"]))
        keys = by_name.get(pk) or by_complex.get(pk)
        if not keys:
            words = set(pk.split())
            hits = [k for k in sorted(dungeons) if len(words) >= 2 and words <= set(name_key(dungeons[k]["name"]).split())]
            keys = hits if len(hits) == 1 else None
        if keys:
            matched.append((page, list(keys)))
        else:
            unmatched.append(page)
    return matched, unmatched


def build_quest_lists(pages: list[dict], dungeons: dict, known_quest_ids) -> tuple[dict[str, list[int]], dict]:
    """({key: [quest ids]}, report). Quest ids not in known_quest_ids are dropped.

    report: unmatched_pages, zero_quests (keys, including dungeons no page matched), ambiguous_wing {page name: keys} (a complex page
    attached to every wing, the page not naming a wing), dropped_unknown_quests {key: ids},
    counts {key: n}.
    """
    matched, unmatched = match_dungeons(pages, dungeons)
    lists: dict[str, list[int]] = {}
    report = {"unmatched_pages": [p["name"] for p in unmatched], "zero_quests": [], "ambiguous_wing": {},
              "dropped_unknown_quests": {}, "counts": {}}
    known = set(known_quest_ids)
    for page, keys in matched:
        if len(keys) > 1:
            report["ambiguous_wing"][page["name"]] = keys
        kept = [q for q in page["quest_ids"] if q in known]
        dropped = [q for q in page["quest_ids"] if q not in known]
        for key in keys:
            merged = lists.setdefault(key, [])
            merged.extend(q for q in kept if q not in merged)
            if dropped:
                report["dropped_unknown_quests"][key] = dropped
    # a generated dungeon no page matched has no quests either
    report["zero_quests"] = sorted(k for k in dungeons if not lists.get(k))
    report["counts"] = {k: len(v) for k, v in sorted(lists.items())}
    return dict(sorted(lists.items())), report


def write_quests_toml(lists: dict[str, list[int]], path: Path) -> None:
    """Writes the quest lists as [dungeons.<key>] tables (atomically, like the poi files)."""
    lines = [HEADER]
    for key in sorted(lists):
        lines.append(f"\n[dungeons.{toml_key(key)}]\nquests = [{', '.join(str(q) for q in lists[key])}]\n")
    write_text_atomic(Path(path), "".join(lines))
